int main(int argc,char** argv){if(argc!=2)return 2;using Reader=ymcc::sensors::sensorapi::PrivateReader;
 const ss::PairChoice requested{ymcc::sensors::sensorapi::sourceId(sensorId(3)),ymcc::sensors::sensorapi::sourceId(sensorId(2))};
 const auto factory=[](const std::shared_ptr<Shared>& state){return [state](ISensorManager** manager){if(!manager)return E_POINTER;*manager=new Manager(state);return S_OK;};};
 {auto state=std::make_shared<Shared>();state->ambiguous=true;Reader reader;expect(reader.start(requested,73,factory(state)),"exact-ID private worker starts without any typed WinRT devices");
  expect(await([&]{const auto s=reader.snapshot();return s.inventoryObserved&&s.pairSelected&&s.queued>=4;}),"actual SDK descriptors and a complete real pair reach the bounded mailbox");
  const auto observed=reader.snapshot();expect(observed.descriptors[0].id.Data1==3&&observed.descriptors[1].id.Data1==2,"descriptor identities agree with requested exact IDs");expect(!observed.descriptors[0].devicePath.empty()&&!observed.descriptors[1].devicePath.empty(),"actual provider paths remain separate from API sensor IDs");
  auto samples=reader.take();bool raw=true,metadata=true;std::array<unsigned,2> kinds{};for(const auto& sample:samples){const auto k=sample.kind==Kind::Gyro?0u:1u;++kinds[k];raw&=sample.axes==(k?std::array<double,3>{.25,-.5,1}:std::array<double,3>{31,32,33});metadata&=sample.generation==73&&sample.timestamp100ns>0&&sample.receiptTick>0;}
  expect(kinds[0]&&kinds[1]&&raw&&metadata,"only requested numeric samples preserve original time and generation");expect(reader.take().empty()||reader.running(),"drain returns copies without manufacturing a stopped-source sample");
  expect(await([&]{return state->gyroReads>=40&&reader.snapshot().dropped>0;}),"worker continues beyond mailbox capacity");const auto bound=reader.snapshot();expect(bound.queued<=32&&bound.dropped>0,"mailbox stays bounded while no owner consumes reports");reader.close();expect(!reader.running()&&reader.take().empty(),"closing reader immediately revokes delivery");expect(await([&]{return Reader::quarantined()==0&&state->managers==0;}),"normally stopping reader retains owner until actual worker exits");balanced(state,"private reader");}
 for(const bool enumeration:{false,true}){auto state=std::make_shared<Shared>();state->ambiguous=true;state->block=!enumeration;state->blockEnumeration=enumeration;
  Reader reader;expect(reader.start(requested,80,factory(state)),"blocking SDK source starts controlled worker");expect(WaitForSingleObject(state->readEntered,1500)==WAIT_OBJECT_0,"SDK worker enters an actual blocked COM-interface call");const auto before=GetTickCount64();reader.close();expect(GetTickCount64()-before<250,"close revokes callbacks without synchronously waiting for blocked COM");expect(Reader::quarantined()>=1,"blocked worker remains an owned quarantined handle");
  Reader second;auto other=std::make_shared<Shared>();other->ambiguous=true;const auto started=second.start(requested,81,factory(other));expect(!started&&other->managers==0,"same-device replacement cannot stack above a quarantined reader");if(started)second.close();SetEvent(state->release);
  expect(await([&]{return Reader::quarantined()==0&&state->managers==0;}),"quarantine clears only after actual blocked worker completes");Reader fresh;auto available=std::make_shared<Shared>();available->ambiguous=true;expect(fresh.start(requested,82,factory(available)),"fresh reader may start after actual old owner exits");expect(await([&]{return fresh.snapshot().queued>=2;}),"new generation obtains its own real observations");fresh.close();expect(await([&]{return Reader::quarantined()==0&&available->managers==0;}),"fresh capture drains without lost COM ownership");balanced(state,"blocked reader");balanced(available,"fresh reader");}
 {Reader reader;auto state=std::make_shared<Shared>();auto bad=requested;bad.gyroId="sensorapi:{not-a-guid}";expect(!reader.start(bad,10,factory(state))&&state->managers==0,"invalid API identity fails before creating a COM worker");expect(!reader.start(requested,0,factory(state))&&state->managers==0,"zero parent generation cannot acquire a worker");}
 const json report={{"status",failures.empty()?"pass":"fail"},{"checks",checks},{"failures",failures},{"actualSdkProvider",true},{"actualPrivateReader",true},{"typedWinrtDevices",false},{"nativeSelectionIntegrated",false},{"hardwareIo",false},{"newProductDlls",json::array()}};
 std::ofstream(argv[1])<<report.dump(2);std::cout<<checks<<" checks / "<<failures.size()<<" failures\n";return failures.empty()?0:1;
}